21	constexpr int64_t kCacheLineSize = 512;
22	
23	at::Tensor foreach_erf(const at::Tensor &x)
24	{
25	    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
26	                   x.scalar_type() == at::kBFloat16,
27	        "foreach_erf: unsupported dtype, expected float32, float16, or bfloat16");
28	    TORCH_CHECK(x.is_contiguous(), "foreach_erf: input must be contiguous");
29	
30	    auto xContig = x.contiguous();
31	    auto dtype = x.scalar_type();
32	
33	    int64_t dtypeFlag = 0;
34	    if (dtype == at::kHalf) {
35	        dtypeFlag = 1;
36	    } else if (dtype == at::kBFloat16) {
37	        dtypeFlag = 2;
38	    }
39	
40	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
41	    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
42	    coreNum = std::min<int32_t>(coreNum, DEFAULT_NUM_PHYSICAL_CORES);
43	    if (coreNum <= 0) coreNum = 1;
44	
45	    uint64_t ubSizeVal;
46	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
47	    int64_t ubSize = static_cast<int64_t>(ubSizeVal);
48	
49	    int64_t totalLen = xContig.numel();
50	    int32_t dtypeSize = static_cast<int32_t>(c10::elementSize(dtype));
51	
52	    // UB tile length calculation:
53	    // fp16/bf16: inQueue(2B*1) + outQueue(2B*1) + castBuf(4B) + outCastBuf(4B) = 12 bytes/elem
54	    //   BUT with alignment margin, use 16 as per design doc
55	    // fp32: inQueue(4B*1) + outQueue(4B*1) + tmpBuf(4B) = 12 bytes/elem
56	    //   BUT use 20 as per elementwise tiling reference
57	    int64_t bytesPerElem = (dtype == at::kFloat) ? 20 : 16;
58	    int64_t kDataUbBudget = ubSize * 3 / 10;
59	    int32_t tileLen = static_cast<int32_t>(kDataUbBudget / bytesPerElem);
60	    tileLen = (tileLen / 32) * 32;
61	    if (tileLen < 32) tileLen = 32;
62	    if (tileLen > 8192) tileLen = 8192;
63	
64	    // Block-level partition with cache line alignment
65	    int32_t elemPerCL = static_cast<int32_t>(kCacheLineSize / dtypeSize);
66	    if (elemPerCL < 1) elemPerCL = 256;
67	    int32_t elemsPerBlock = static_cast<int32_t>((totalLen + coreNum - 1) / coreNum);
68	    elemsPerBlock = ((elemsPerBlock + elemPerCL - 1) / elemPerCL) * elemPerCL;
69	    if (elemsPerBlock < elemPerCL) elemsPerBlock = elemPerCL;
70	
71	    int32_t formerNum = static_cast<int32_t>(totalLen / elemsPerBlock);
72	    int32_t formerLen = elemsPerBlock;
73	    int32_t tailLen = static_cast<int32_t>(totalLen % elemsPerBlock);
74	    int32_t tailNum = (tailLen > 0) ? 1 : 0;
75	
76	    int32_t numTilesPerBlock = static_cast<int32_t>((elemsPerBlock + tileLen - 1) / tileLen);
77	
78	    auto yOut = at::empty_like(xContig);
79	
80	    // All params as left values for EXEC_KERNEL_CMD
81	    int32_t totalLenI32 = static_cast<int32_t>(totalLen);
82	    uint32_t blockDim = static_cast<uint32_t>(formerNum + tailNum);
83	    int32_t dtypeFlagI32 = static_cast<int32_t>(dtypeFlag);
84	
85	    EXEC_KERNEL_CMD(foreach_erf, blockDim,
86	                    xContig, yOut,
87	                    totalLenI32, tileLen,
88	                    formerNum, formerLen, tailNum, tailLen,
89	                    elemsPerBlock, numTilesPerBlock, dtypeFlagI32);
90	
91	    return yOut;
92	}
