115	            pipe.InitBuffer(outQueue_, BUFFER_NUM, N_ * sizeof(dataType));
116	
117	            if constexpr (!std::is_same_v<dataType, float>) {
118	                pipe.InitBuffer(castBuf_, N_ * sizeof(float));
119	                pipe.InitBuffer(outCastBuf_, N_ * sizeof(float));
120	            } else {
121	                pipe.InitBuffer(tmpBuf_, N_ * sizeof(float));
122	            }
123	        }
124	    }
