126	    __aicore__ inline void Process()
127	    {
128	        if ASCEND_IS_AIV {
129	            int32_t coreIdx = AscendC::GetBlockIdx();
130	            int32_t blockOffset;
131	
132	            if (coreIdx < formerNum_) {
133	                blockOffset = coreIdx * formerLength_;
134	            } else if (tailNum_ > 0 && coreIdx == formerNum_) {
135	                blockOffset = formerNum_ * formerLength_;
136	            } else {
137	                return;
138	            }
139	
140	            for (int32_t t = 0; t < tilesPerBlock_; ++t) {
141	                int32_t tileStart = blockOffset + t * N_;
142	                int32_t curLen = N_;
143	                if (tileStart + curLen > totalLen_) {
144	                    curLen = totalLen_ - tileStart;
145	                    if (curLen <= 0) continue;
146	                }
147	                int32_t blockEnd = blockOffset + elemsPerBlock_;
148	                if (blockEnd > totalLen_) blockEnd = totalLen_;
149	                if (tileStart >= blockEnd) continue;
150	                if (tileStart + curLen > blockEnd) {
151	                    curLen = blockEnd - tileStart;
152	                }
153	
154	                CopyIn(tileStart, curLen);
155	                Compute(curLen);
156	                CopyOut(tileStart, curLen);
157	            }
