// ForeachNorm: L2-norm reduction → Y = sqrt(sum(X^2))
// Pattern: foreach tensor → flatten → kernel call → scalar output

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// GM <-> UB helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Main kernel
// =========================================================================

template <typename dataType>
class KernelForeachNorm {
public:
    __aicore__ inline void Init(
        GM_ADDR xGm, GM_ADDR yGm,
        int32_t totalLength, int32_t tileLength, int32_t dtypeFlag)
    {
        totalLen_ = totalLength;
        N_ = tileLength;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(xGm), totalLen_);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), 1);

        if ASCEND_IS_AIV {
            // Input / output queues
            pipe.InitBuffer(inQueue_, BUFFER_NUM, N_ * sizeof(dataType));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, 1 * sizeof(dataType));

            if constexpr (!std::is_same_v<dataType, float>) {
                // fp16/bf16: need cast buffers
                pipe.InitBuffer(castBuf_, N_ * sizeof(float));       // fp16→fp32 cast
            }
            // Common compute buffers (always in fp32 for stability)
            pipe.InitBuffer(sqBuf_, N_ * sizeof(float));             // squared values
            pipe.InitBuffer(redBuf_, N_ * sizeof(float));            // ReduceSum work buffer
            pipe.InitBuffer(sumBuf_, sizeof(float));                 // per-tile sum result (1 elem)
            pipe.InitBuffer(accBuf_, sizeof(float));                 // accumulator (1 elem)
            pipe.InitBuffer(sqrtBuf_, sizeof(float));                // sqrt result (1 elem)
            pipe.InitBuffer(tmpBuf_, sizeof(float));                 // scalar temp (1 elem)
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            // Initialize accumulator to zero
            auto accLocal = accBuf_.Get<float>();
            AscendC::Duplicate(accLocal, 0.0f, 1);

            // Pre-compute: accFp32_ member is set only after first Compute
            // to avoid repeated Get() calls. We use the accBuf_ directly.

            // Main tile loop
            int32_t numTiles = totalLen_ / N_;
            if (totalLen_ % N_ != 0) {
                numTiles += 1;
            }

            for (int32_t t = 0; t < numTiles; ++t) {
                int32_t tileStart = t * N_;
                int32_t curLen = N_;
                if (tileStart + curLen > totalLen_) {
                    curLen = totalLen_ - tileStart;
                }

                CopyIn(tileStart, curLen);
                Compute(curLen);
            }

            // Finalize: sqrt(acc) → cast → output scalar
            Finalize();
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t start, int32_t count)
    {
        xInLocal_ = inQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[start], static_cast<uint32_t>(count));
        inQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void Compute(int32_t count)
    {
        // DeQue input tile
        xInLocal_ = inQueue_.DeQue<dataType>();

        // --- Step 1: Cast to fp32 ---
        AscendC::LocalTensor<float> xFp32;
        if constexpr (std::is_same_v<dataType, float>) {
            xFp32 = xInLocal_.template ReinterpretCast<float>();
        } else {
            xFp32 = castBuf_.Get<float>();
            AscendC::Cast(xFp32, xInLocal_, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
