        // --- Step 2: Square ---
        auto sqFp32 = sqBuf_.Get<float>();
        AscendC::Mul(sqFp32, xFp32, xFp32, count);

        // --- Step 3: ReduceSum tile ---
        auto reduceWorkBuf = redBuf_.Get<float>();
        auto sumFp32 = sumBuf_.Get<float>();
        AscendC::ReduceSum<float>(sumFp32, sqFp32, reduceWorkBuf, count);

        // --- Step 4: Accumulate ---
        AscendC::PipeBarrier<PIPE_V>();
        float tileSum = sumFp32.GetValue(0);
        auto accLocal = accBuf_.Get<float>();
        AscendC::Adds(accLocal, accLocal, tileSum, 1);

        // Free input
        inQueue_.FreeTensor(xInLocal_);
    }

    __aicore__ inline void Finalize()
    {
        // Read accumulated value
        AscendC::PipeBarrier<PIPE_ALL>();
        auto accLocal = accBuf_.Get<float>();
        float accVal = accLocal.GetValue(0);

        // --- Step 5: sqrt(acc) ---
        auto tmpFp32 = tmpBuf_.Get<float>();
        tmpFp32.SetValue(0, accVal);
        auto sqrtFp32 = sqrtBuf_.Get<float>();
        AscendC::Sqrt(sqrtFp32, tmpFp32, 1);

        // --- Step 6: Cast to output dtype + write to GM ---
        auto yOutLocal = outQueue_.AllocTensor<dataType>();

        if constexpr (std::is_same_v<dataType, float>) {
            auto yOutFp32 = yOutLocal.template ReinterpretCast<float>();
            AscendC::DataCopy(yOutFp32, sqrtFp32, 1);
        } else {
            AscendC::Cast(yOutLocal, sqrtFp32, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::PipeBarrier<PIPE_V>();
        }

        outQueue_.EnQue(yOutLocal);

        // CopyOut: UB → GM
        yOutLocal = outQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[0], yOutLocal, 1);
        outQueue_.FreeTensor(yOutLocal);
    }

