    AscendC::TPipe pipe;
    int32_t totalLen_;
    int32_t N_;

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue_;

