    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;    // per-tile sum
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;    // accumulator
    AscendC::TBuf<AscendC::TPosition::VECCALC> sqrtBuf_;   // sqrt result
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;    // scalar temp

    AscendC::LocalTensor<dataType> xInLocal_;
};

