#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_foreach_norm.h"

namespace ascend_kernel {

at::Tensor foreach_norm(const at::Tensor &x)
{
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
                   x.scalar_type() == at::kBFloat16,
        "foreach_norm: unsupported dtype, expected float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "foreach_norm: input must be contiguous");

    auto xContig = x.contiguous();
    auto dtype = x.scalar_type();

    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) {
        dtypeFlag = 1;
    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSizeVal;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
    int64_t ubSize = static_cast<int64_t>(ubSizeVal);

    int64_t totalLen = xContig.numel();
    int32_t dtypeSize = static_cast<int32_t>(c10::elementSize(dtype));

    // UB tile length calculation:
    // fp16/bf16: inBuf(2B) + castBuf(4B) + sqBuf(4B) + redBuf(4B) = 14 bytes/elem
    //   + sumBuf+accBuf+sqrtBuf+tmpBuf (≈16B) → use coefficient 16
    //   tile_size = UB_budget / 16
    //   UB_budget = ubSize * 3/10 ≈ 57KB for 192KB UB → tile ≈ 3648
    //   Align to 32: tile = 3584 or 2048 (conservative)
    // fp32: inBuf(4B) + sqBuf(4B) + redBuf(4B) = 12 bytes/elem
    //   + sumBuf+accBuf+sqrtBuf+tmpBuf (≈16B) → use coefficient 20
    //   tile_size = UB_budget / 20 ≈ 2880 for 192KB UB
    //   Align to 32: tile = 2816 or 1024 (conservative)
    int64_t bytesPerElem = (dtype == at::kFloat) ? 20 : 16;
    int64_t kDataUbBudget = ubSize * 3 / 10;
    int32_t tileLen = static_cast<int32_t>(kDataUbBudget / bytesPerElem);
    tileLen = (tileLen / 32) * 32;
    if (tileLen < 32) tileLen = 32;
    if (tileLen > 8192) tileLen = 8192;

    // Output: 1-element tensor (scalar)
    auto yOut = at::empty({1}, xContig.options());

    // All params as left values for EXEC_KERNEL_CMD
    int32_t totalLenI32 = static_cast<int32_t>(totalLen);
    uint32_t blockDim = 1;  // Single core: no cross-core synchronization needed
    int32_t dtypeFlagI32 = static_cast<int32_t>(dtypeFlag);

    EXEC_KERNEL_CMD(foreach_norm, blockDim,
                    xContig, yOut,
                    totalLenI32, tileLen, dtypeFlagI32);

    return yOut;
}

}  // namespace ascend_kernel
